 records[i]={**o,'outcome':outcome,'review_depth':depth,'primary_locus':locus,'source_receipt':receipt,'historical_check':{'artifact':'history-matches.txt','result':'Matches were reservation references or unrelated long numeric strings/path fragments; no prior technical disposition identified by the ID/title screen. Protected Ramsey family was explicitly respected. This is bounded campaign search, not global novelty.'},'mathematical_attempt':attempt,'precise_remaining_gap':gap,'source_own_lemma_gate':'No eligible full endpoint survives; routine/source-settled distinctions recorded in mathematical_attempt. No novelty claim based on an open label.','search_coverage_logs':[],'registry_scope_limit':'Live HEAD and complete tree path screens are not proof-body or worldwide novelty clearance. Adjacent LiUncu Conjecture 1.3 polynomial proof read; no automatic CP Conjecture 7.1 bridge claimed.','lean_packet':None,'accepted_credit':0}
